class Example {
    StringBuilder calls = new StringBuilder();
    String format() {
        String a = prefix() + (value() + ""); // violation
        String b = prefix() + ("" + value()); // violation
        return a + b;
    }
    String prefix() {
        calls.append("prefix;");
        return "prefix";
    }
    Object value() {
        calls.append("value;");
        return new Object() {
            @Override
            public String toString() {
                calls.append("toString;");
                return "value";
            }
        };
    }
}

